// View defines model for View.
type View struct {
	// Appends 作者在主帖发布的追加追评（按追加时间升序），保留首次正文、评分与教师归属不变。公开视图仅包含已发布追评，无可见追评时省略。
	Appends   *[]Append `json:"appends,omitempty"`
	Author    Author    `json:"author"`
	Body      string    `json:"body"`
	CanEdit   bool      `json:"can_edit"`
	Downvotes int       `json:"downvotes"`
	Featured  *bool     `json:"featured,omitempty"`
	Id        string    `json:"id"`
	Kind      string    `json:"kind"`
	Mine      bool      `json:"mine"`

	// ModerationReasonCode 面向作者展示的封闭结构化审核原因枚举键，映射前端八语言翻译键，不含管理员内部自由文本备注或举报证据。
	ModerationReasonCode *ModerationReasonCode `json:"moderation_reason_code,omitempty"`
	MyVote               int                   `json:"my_vote"`

	// ParentAuthorHandle 回复所指向父楼层作者的讨论内脱敏标识（如 author 或匿名讨论句柄），根评价或撤回父帖省略。
	ParentAuthorHandle *string `json:"parent_author_handle,omitempty"`
	ParentId           *string `json:"parent_id,omitempty"`

	// ParentVisible 回复所指向父楼层当前是否对外公开可见（含认证教师回复实名授权核验），不返回不可见父楼层正文；根评价省略。
	ParentVisible *bool      `json:"parent_visible,omitempty"`
	PublishedAt   *time.Time `json:"published_at"`

	// Ratings 固定五维评分数组，下标依次为：0=推荐度（recommendation）、1=内容质量（content_quality）、2=课程难度（difficulty）、3=工作量（workload）、4=考核给分（grading）。课程评价发布时各维取 1..5，草稿或非课程评价可为 0。
	Ratings []int `json:"ratings"`

	// ReplyCount 评价列表中的根评价附带当前请求人可见的已发布回复总数，包括嵌套回复。删除、隐藏、撤回、到期及必需实名授权撤销的回复不计入。本人列表仅在仍有当前内容阅读权限时提供；详情和回复行可省略。 仅 include_reply_preview=true 时返回。
	ReplyCount *int `json:"reply_count,omitempty"`

	// ReplyPreview 与 reply_count 一起提供，按创建时间升序、ID 升序的最早 3 条可见回复。无回复时为空数组。预览回复不再嵌套预览，使用与回复列表相同的当前匿名、署名与公开标签规则。 仅 include_reply_preview=true 时返回。
	ReplyPreview *[]View `json:"reply_preview,omitempty"`
	Revision     int     `json:"revision"`
	RootId       string  `json:"root_id"`
	SchoolId     string  `json:"school_id"`
	State        string  `json:"state"`

	// TargetId  体育项目评价继续使用 kind=course，target_id 为 catalog 返回的体育项目 ID。原编号体育课程被隐藏后返回 404。
	TargetId string `json:"target_id"`

	// TeacherId  体育项目评价必须选择一个教师，并且教师来自本人同一项目、同一学期的有效教学班；缺少教师返回 invalid_input，越权教师返回 forbidden。
	TeacherId *string `json:"teacher_id,omitempty"`

	// TeacherIds 课程评价发布时记录的任课教师归属快照（单选教师时为该教师，未单选教师时为该学期本人选课任课教师并集）；非课程评价或无教师归属时省略。 仅在 include_teacher_ids=true 时返回。
	TeacherIds *[]string `json:"teacher_ids,omitempty"`
	TermId     *string   `json:"term_id,omitempty"`
	Title      string    `json:"title"`
	Upvotes    int       `json:"upvotes"`
}

